mapper.select:
SELECT 'DR' AS recordType, A.MDFM_CLS_CD AS recordDetailType, COMN.COMN_CD_NM AS itemType, CASE WHEN A.MDFM_CLS_CD = 'D020' THEN FORM.MDFM_NM ELSE COMN.COMN_CD_NM END AS itemNm, CASE WHEN A.MDFM_CLS_CD IN ('D001', 'D002', 'D003', 'D004', 'D031') THEN A.MED_DT ELSE A.MDF_REC_DTM::DATE END AS writingDate, A.WRTR_DEPT_CD AS writingDeptCd, DEPT.DEPT_NM AS writingDeptNm, A.WRT_STF_NO AS writerStfNo, STFF.STF_NM AS writerNm, NULL AS keyId, A.PACT_ID AS pactId, DECODE(A.PACT_TP_CD, 'I', '입원', 'O', '외래', 'E', '응급', NULL) AS pactTpCd, ROW_NUMBER() OVER (PARTITION BY TO_CHAR(A.MDF_REC_DTM, 'YYYY-MM-DD') ORDER BY A.REC_DTM DESC) AS sortSeq, NULL AS note, A.MDFM_ID AS mdfmId, A.MDFM_FOM_SEQ AS mdfmFomSeq, A.MDRC_ID AS mdrcId, A.MDRC_FOM_SEQ AS mdrcFomSeq, NULL AS examKey, NULL AS pacsImgIptnCd, NULL AS accsId, NULL AS recType, NULL AS geneExmYn, CASE WHEN A.MDRC_WRT_STS_CD > 10 THEN 'Y' END AS mdrcWrtStsCdYn, NULL AS opExptRegId FROM ODS.S_MRDDRECM A LEFT OUTER JOIN ODS.S_CCCCCSTE COMN ON COMN.COMN_GRP_CD = 'RDO062' AND A.MDFM_CLS_DTL_CD = COMN.COMN_CD LEFT OUTER JOIN ODS.S_PDEDBMSM DEPT ON A.WRTR_DEPT_CD = DEPT.DEPT_CD LEFT OUTER JOIN ODS.S_CNLRRUSD STFF ON A.WRT_STF_NO = STFF.STF_NO LEFT OUTER JOIN ODS.S_MRFMFORM FORM ON A.MDFM_ID = FORM.MDFM_ID AND A.MDFM_FOM_SEQ = FORM.MDFM_FOM_SEQ WHERE 1 = 1 AND A.PT_NO = #{ptNo} AND A.MDFM_CLS_CD NOT IN ('D005', 'D006', 'D007') AND A.MDFM_CLS_CD IN
#{item}
AND ( (A.MDFM_CLS_CD IN ('D001', 'D002', 'D003', 'D004', 'D031') AND A.MED_DT::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE) OR (A.MDFM_CLS_CD NOT IN ('D001', 'D002', 'D003', 'D004', 'D031') AND A.MDF_REC_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE) ) AND A.PACT_TP_CD = DECODE(#{pactTpCd}, 'ALL', A.PACT_TP_CD, #{pactTpCd}) AND A.LST_YN = 'Y' AND A.MDRC_DC_TP_CD = 'C' AND A.PT_MED_DEPT_CD = #{deptCd} AND A.WRTR_DEPT_CD = #{deptCd} AND A.WK_SID = #{writerStfNo} AND A.WK_STF_NO = #{writerStfNo} AND NOT EXISTS(SELECT 1 FROM ODS.S_MRFMFORM Z WHERE A.MDFM_ID = Z.MDFM_ID AND A.MDFM_FOM_SEQ = Z.MDFM_FOM_SEQ AND Z.MDFM_CLS_CD = 'D020' AND Z.MDFM_APY_CTRA_CD = 4) AND NOT EXISTS(SELECT 1 FROM ODS.S_CNLRRUSD Z WHERE Z.STF_NO = A.WRT_STF_NO AND Z.OCTY_TP_CD = 'Z06') ORDER BY writingDate DESC, sortSeq

SELECT RCV_DEPT_CD
FROM ODS.S_MRDDRCNE
WHERE MDRC_ID = #{mdrcId}
  AND MDRC_FOM_SEQ = #{mdrcFomSeq}
ORDER BY RER_SEQ

SELECT 'DR' AS recordType , B.MDFM_CLS_CD AS recordDetailType , COMN.COMN_CD_NM AS itemType , COMN.COMN_CD_NM AS itemNm , A.OP_EXPT_DT AS writingDate , NULL AS writingDeptCd , NULL AS writingDeptNm , B.LSH_STF_NO AS writerStfNo , STFF.STF_NM AS writerNm , NULL AS keyId , NULL AS pactId , NULL AS pactTpCd , ROW_NUMBER() OVER (PARTITION BY A.OP_EXPT_DT ORDER BY A.OP_EXPT_DT DESC) AS sortSeq , NULL AS note , NULL AS mdfmId , NULL AS mdfmFomSeq , NULL AS mdrcId , NULL AS mdrcFomSeq , NULL AS examKey , NULL AS pacsImgIptnCd , NULL AS accsId , NULL AS recType , NULL AS geneExmYn , 'Y' AS mdrcWrtStsCdYn , A.OP_EXPT_REG_ID AS opExptRegId FROM ODS.S_MRDDRARD A INNER JOIN ODS.S_MRDDRAFE B ON A.OP_EXPT_REG_ID = B.OP_EXPT_REG_ID AND B.AFCHG_ANRM_REC_VAL_ID IS NULL INNER JOIN ODS.S_MOOOPPAM C ON C.OP_EXPT_REG_ID = A.OP_EXPT_REG_ID LEFT OUTER JOIN ODS.S_CCCCCSTE COMN ON COMN.COMN_GRP_CD = 'RDO062' AND B.MDFM_CLS_DTL_CD = COMN.COMN_CD LEFT OUTER JOIN ODS.S_CNLRRUSD STFF ON B.LSH_STF_NO = STFF.STF_NO WHERE 1 = 1 AND A.PT_NO = #{ptNo} AND B.MDFM_CLS_CD IN
#{item}
AND A.LSH_DTM::DATE BETWEEN #{searchFromDate}::DATE AND #{searchToDate}::DATE AND B.LSH_DTM = (SELECT MAX(LSH_DTM) FROM ODS.S_MRDDRAFE D WHERE D.OP_EXPT_REG_ID = B.OP_EXPT_REG_ID AND D.MDFM_CLS_CD = B.MDFM_CLS_CD AND D.AFCHG_ANRM_REC_VAL_ID IS NULL) GROUP BY B.MDFM_CLS_CD, B.MDFM_CLS_DTL_CD, COMN.COMN_CD_NM, A.OP_EXPT_DT, B.LSH_STF_NO, STFF.STF_NM, A.OP_EXPT_REG_ID
